if($transferSimple??false){require __DIR__.'/transfer-payment.php';return;}
$tr=static fn(string $text):string=>\Kulturhus\Native\Language\TransferMessages::text($text,$transferMessages);
$trCatalogue=array_diff_key(receiptPaymentContext($transferEntry,$_GET,false),array_fill_keys(['view','tab','entry'],true));foreach(['transfer_q','transfer_state','transfer_page','transfer_manual']as$control)if(is_string($_GET[$control]??null))$trCatalogue[$control]=$_GET[$control];
$trUrl=static fn(array $query=[]):string=>url(['view'=>'finance','tab'=>'receipts','entry'=>$transferEntry]+($transferOrder!==''?['transfer_order'=>$transferOrder]:[])+$query+$trCatalogue);
$trRaw=static fn(array $source,string $name,string $default=''):string=>is_string($source[$name]??$default)?($source[$name]??$default):'';
$trField=static function(string $name,string $value,bool $readonly=false,string $type='text'):void{
    if($type==='date'&&$value!==''&&(!preg_match('/\A([0-9]{4})-([0-9]{2})-([0-9]{2})\z/D',$value,$parts)||!checkdate((int)$parts[2],(int)$parts[3],(int)$parts[1])))$type='text';
    if($type==='textarea'||strpbrk($value,"\r\n")!==false):?><textarea class="form-control" name="<?=e($name)?>"<?=$readonly?' readonly':''?>><?="\n".e($value)?></textarea><?php else:?><input class="form-control" type="<?=e($type)?>" name="<?=e($name)?>" value="<?=e($value)?>"<?=$readonly?' readonly':''?>><?php endif;
};
$trStates=['prepared'=>'Vorbereitet','approved'=>'Freigegeben','exported'=>'Bankdatei exportiert','submitted'=>'Einreichung dokumentiert','cancelled'=>'Verworfen'];
$trOperations=['prepare'=>'Neuen Überweisungsauftrag vorbereiten','pay'=>'Zahlung mit FinTS','approve'=>'Vorbereiteten Zahlungsauftrag freigeben','export'=>'Genau diese Bankdatei zum manuellen Upload exportieren','submitted'=>'Tatsächliche Einreichung anhand Nachweis dokumentieren','cancel'=>'Noch nicht exportierten Auftrag verwerfen','fints_submitted'=>'Tatsächliche FinTS-Annahme anhand Banknachweis dokumentieren','fints_not_sent'=>'Bestätigte Nichtannahme durch die Bank dokumentieren'];
$trPending=$transferState['context']['transport']['pending']??false;$trAvailable=$transferOrder===''?['prepare']:(['prepared'=>['approve','cancel'],'approved'=>['export','cancel'],'exported'=>['export','submitted'],'submitted'=>[],'cancelled'=>[]][$transferState['context']['order']['state']??'cancelled']??[]);if(($_GET['transfer_manual']??null)!=='1')$trAvailable=array_values(array_diff($trAvailable,['export']));if($trPending)$trAvailable=['fints_submitted','fints_not_sent'];if(!($transferState['can_approve']??false))$trAvailable=array_values(array_intersect($trAvailable,['prepare','cancel']));
?>
