<?php if($context=$transferState['context']):$trOrder=$context['order'];?><section class="card" data-transfer-current><h3><?=e($tr('Tatsächlicher aktueller Überweisungsauftrag'))?></h3><p><?=e($tr($trStates[$trOrder['state']]))?> · <?=e(euro($trOrder['total_cents']))?> · <?=e($trOrder['execution_date'])?></p><?php if($trOrder['bank_reference']!==''):?><h4><?=e($tr('Dokumentierte Bankauftragsnummer'))?></h4><pre><?="\n".e($trOrder['bank_reference'])?></pre><?php endif ?>
<?php if(in_array($trOrder['state'],['exported','submitted'],true)&&$transferState['can_approve']):?><a class="btn btn-outline theme-secondary" data-transfer-order-xml download href="<?=e($trUrl(['transfer_order_xml'=>$trOrder['id']]))?>"><?=e($tr('Bereits exportierte ursprüngliche Bankdatei lesend herunterladen'))?></a><p><?=e($tr('Der historische Dateidownload ändert keinen Auftragsstatus und bestätigt keine erneute Einreichung. Reichen Sie dieselbe Datei nicht mehrfach bei der Bank ein.'))?></p><?php endif ?>
<?php if($trOrder['state']==='approved'&&!$trPending&&$transferState['can_approve']):?><a data-fints-payment-link class="btn btn-solid theme-primary" href="<?=e(url(['view'=>'finance','tab'=>'bank','account'=>$trOrder['account_id'],'fints'=>1,'payment'=>'transfer','payment_order'=>$trOrder['id']]))?>#fints-payment"><?=e($tr('Mit FinTS überweisen'))?></a><?php endif ?>
