<?php $transferShownSource=$first['result']['source'];require __DIR__.'/transfer-source-native.php';if($transferState['can_write']&&$trAvailable):?><a class="btn btn-outline theme-secondary" href="<?=e($trUrl(['transfer_new'=>'1']))?>#invoice-transfer"><?=e($tr('Eine weitere Überweisungsentscheidung bewusst neu öffnen'))?></a><?php endif ?></section><?php endif ?>
<?php if(!$transferState['receipt']&&($draft=$transferDraft)&&$draft['accepted']===null):$raw=$draft['input'];$review=$draft['review'];$readonly=$draft['pending']||!$transferState['can_write'];?><section class="card" data-transfer-editor>
