<form method="post" action="<?=e($trUrl())?>#invoice-transfer" novalidate data-transfer-form><?=csrf().hidden('action','transfer-native').hidden('transfer_draft',$draft['id']).hidden('transfer_revision',\Kulturhus\Verein\Finance\Banking\NativeTransfer\TransferDraft::revision($draft))?>
<?php if($readonly)echo hidden('operation',$raw['operation']);?><label><?=e($tr('Gewünschte Überweisungsaktion'))?><select class="form-control" name="operation"<?=$readonly?' disabled':''?>><option value=""><?=e($tr('Eine Aktion bewusst auswählen'))?></option><?php if($raw['operation']!==''&&!in_array($raw['operation'],$trAvailable,true)):?><option selected value="<?=e($raw['operation'])?>"><?=e(isset($trOperations[$raw['operation']])?$tr($trOperations[$raw['operation']]):$raw['operation'])?></option><?php endif;foreach($trAvailable as$operation):?><option value="<?=e($operation)?>"<?=$raw['operation']===$operation?' selected':''?>><?=e($tr($trOperations[$operation]))?></option><?php endforeach ?></select></label>
