<?php if($field==='account'):$values=array_column($transferState['accounts'],'name','id');elseif($field==='transfer_mode'):$values=['standard'=>$tr('Normale SEPA-Überweisung'),'instant'=>$tr('Echtzeitüberweisung')];else:$values=null;endif;
if($values!==null){if($readonly)echo hidden('data['.$field.']',$raw['data'][$field]);?><select class="form-control" name="data[<?=e($field)?>]"<?=$readonly?' disabled':''?>><option value=""><?=e($tr('Bewusst auswählen'))?></option><?php if($raw['data'][$field]!==''&&!isset($values[$raw['data'][$field]])):?><option selected value="<?=e($raw['data'][$field])?>"><?=e($raw['data'][$field])?></option><?php endif;foreach($values as$value=>$option):?><option value="<?=e($value)?>"<?=$raw['data'][$field]===$value?' selected':''?>><?=e($option)?></option><?php endforeach ?></select><?php }else{$trField('data['.$field.']',$raw['data'][$field],$readonly,$field==='execution_date'?'date':'text');}?></label><?php endforeach ?>
