<?=hidden('transfer_key',$draft['key'])?><?php if($transferState['can_write']):?><label class="general-settings-check"><input class="check" type="checkbox" name="transfer_approved" value="1"><span><?=e($tr('Genau diese Rechnung, dieser Auftrag, Betrag, Empfänger, Zahlungsart und alle ganzen Angaben einschließlich des erforderlichen Banknachweises sind geprüft.'))?></span></label><button class="btn btn-solid theme-primary" name="transfer_intent" value="accept"><?=e($tr('Geprüfte Überweisungsentscheidung bewusst speichern'))?></button><?php endif ?></section><?php endif ?></form></section><?php endif ?>
